/* Two of the numbers are not in the table as the file
   holds it: how big one variant of a statement type is.
   The language sets them when it starts, and a table
   without them lays down a statement with no variant in
   it at all. */
void kokr61_viasizes(void)
{
    kokr61_vstmtbl[1].stride = 4;
    kokr61_vstmtbl[1].varlen = 4;
    kokr61_vstmtbl[2].stride = 7;
    kokr61_vstmtbl[2].varlen = 7;
}
